/**
 * @param {number} n
 * @param {number} k
 * @param {number[][]} invocations
 * @return {number[]}
 */
var remainingMethods = function(n, k, invocations) {
    const outMap = new Map();
    const inMap = new Map();

    for (const [u, v] of invocations) {
        if (!outMap.has(u)) {
            outMap.set(u, new Set());
        }
        outMap.get(u).add(v);

        if (!inMap.has(v)) {
            inMap.set(v, new Set());
        }
        inMap.get(v).add(u);
    }

    const dp = Array(n).fill(0);
    dp[k] = 1;

    const dfs = (pos) => {
        const neighbours = outMap.get(pos) || []; 

        for (const con of neighbours) {
            if (dp[con] === 0) {
                dp[con] = 1;
                dfs(con);
            }
        }
    };
    dfs(k);

    for (let i = 0; i < n; i++) {
        if (dp[i] === 1) {
            const neighbours = inMap.get(i) || [];

            for (const con of neighbours) {
                if (dp[con] === 0) {
                    return Array.from({ length: n }, (_, i) => i);
                }
            }
        }
    }

    let stack = [];

    for (let i = 0; i < n; i++) {
        if (dp[i] === 1) {
            dp[i] = 2;
            stack.push(i);
        }
    }

    while (stack.length > 0) {
        let next = [];

        for (const node of stack) {
            const neighbours = [inMap.get(node) || [], outMap.get(node) || []];

            for (const con of neighbours) {
                if (dp[con] === 0) {
                    dp[con] = 2;
                    next.push(con);
                }
            }
        }

        stack = next;
    }

    const res = [];

    for (let i = 0; i < n; i++) {
        if (dp[i] === 0) {
            res.push(i);
        }
    }

    return res;
};
